<script setup>
import { onMounted, ref } from 'vue';import { useI18n } from 'vue-i18n';import { useAuthStore } from '../stores/auth';import * as api from '../api/notifications';import { fetchAdminCourses } from '../api/admin';
const { t, locale } = useI18n(), auth = useAuthStore();const items = ref([]), form = ref(null), roles = ref([]), courseIds = ref([]), courses = ref([]), courseSearch = ref(''), coursePage = ref(1), courseLastPage = ref(1), editing = ref(null), preview = ref(null), error = ref(false), busy = ref(false), meta = ref({ current_page: 1, last_page: 1 });
const roleNames = ['student', 'instructor', 'admin', 'content_manager', 'sales_support'];
function localDate(value) { if (!value) return null; const d = new Date(value); return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0,16); }
async function loadCourses(page = 1) { if (!auth.can('courses.view')) return; try { const result = await fetchAdminCourses({ search: courseSearch.value || undefined, page, per_page: 25 }); courses.value = result.items; coursePage.value = result.meta.current_page; courseLastPage.value = result.meta.last_page; } catch { error.value = true; } }
function start(item = null) { editing.value = item?.id ?? null; form.value = item ? JSON.parse(JSON.stringify({ title: item.title, body: item.body, audience: item.audience, publish_at: localDate(item.publish_at), expires_at: localDate(item.expires_at) })) : { title: { ar: '', en: '' }, body: { ar: '', en: '' }, audience: { kind: 'all' }, publish_at: null, expires_at: null }; roles.value = item?.audience.roles ?? []; courseIds.value = [...(item?.audience.course_ids ?? [])]; preview.value = null; void loadCourses(); }
function payload() { const audience = { kind: form.value.audience.kind }; if (audience.kind === 'roles') audience.roles = [...roles.value]; if (audience.kind.startsWith('course_')) audience.course_ids = [...courseIds.value]; return { ...form.value, audience, publish_at: form.value.publish_at ? new Date(form.value.publish_at).toISOString() : null, expires_at: form.value.expires_at ? new Date(form.value.expires_at).toISOString() : null }; }
async function load(page = 1) { error.value = false; try { const result = await api.fetchStaffAnnouncements(page); items.value = result.data; meta.value = result; } catch { error.value = true; } }
async function act(operation) { if (busy.value) return; busy.value = true; error.value = false; try { await operation(); await load(); } catch { error.value = true; } finally { busy.value = false; } }
async function previewAudience() { preview.value = (await api.previewAudience({ audience: payload().audience })).count; }
function publish(id) { return act(() => api.publishAnnouncement(id)); }
function archive(id) { return act(() => api.archiveAnnouncement(id)); }
async function save() { await api.saveAnnouncement(payload(), editing.value); form.value = null; }
onMounted(load);
</script>
<template><section class="mx-auto max-w-4xl space-y-5 p-4" :dir="locale === 'ar' ? 'rtl' : 'ltr'"><header class="flex flex-wrap items-center justify-between gap-3"><h1 class="text-2xl font-black">{{ t('notifications.manageAnnouncements') }}</h1><button type="button" class="min-h-11 rounded-xl bg-primary px-4 text-brand-dark" @click="start()">{{ t('notifications.newAnnouncement') }}</button></header><p v-if="error" role="alert" class="text-red-700">{{ t('notifications.error') }}</p><form v-if="form" class="space-y-4 rounded-2xl border border-slate-200 bg-white p-5" @submit.prevent="act(save)"><fieldset v-for="language in ['ar', 'en']" :key="language" class="space-y-2"><legend class="font-bold">{{ language === 'ar' ? 'العربية' : 'English' }}</legend><label class="block">{{ t('notifications.announcementTitle') }}<input v-model="form.title[language]" :dir="language === 'ar' ? 'rtl' : 'ltr'" required maxlength="255" class="block min-h-11 w-full rounded-xl border border-slate-300 px-3"></label><label class="block">{{ t('notifications.body') }}<textarea v-model="form.body[language]" :dir="language === 'ar' ? 'rtl' : 'ltr'" required maxlength="10000" rows="4" class="block w-full rounded-xl border border-slate-300 p-3" /></label></fieldset><label class="block">{{ t('notifications.audience') }}<select v-model="form.audience.kind" class="min-h-11 rounded-xl border border-slate-300 px-3"><option v-for="kind in ['all', 'roles', 'course_students', 'course_instructors']" :key="kind" :value="kind">{{ t(`notifications.audiences.${kind}`) }}</option></select></label><div v-if="form.audience.kind === 'roles'" class="flex flex-wrap gap-4"><label v-for="role in roleNames" :key="role"><input v-model="roles" type="checkbox" :value="role">{{ t(`notifications.roles.${role}`) }}</label></div><fieldset v-if="form.audience.kind.startsWith('course_')" class="space-y-2"><legend class="font-bold">{{ t('notifications.courses') }}</legend><div class="flex gap-2"><input v-model="courseSearch" :aria-label="t('notifications.courseSearch')" class="min-w-0 flex-1 rounded-xl border border-slate-300 px-3" @keydown.enter.prevent="loadCourses()"><button type="button" class="min-h-11 px-3" @click="loadCourses()">{{ t('notifications.courseSearch') }}</button></div><label v-for="course in courses" :key="course.id" class="flex min-h-11 items-center gap-2"><input v-model="courseIds" type="checkbox" :value="course.id">{{ course.title }}</label><div class="flex justify-between"><button type="button" :disabled="coursePage <= 1" class="min-h-11 px-3" @click="loadCourses(coursePage - 1)">{{ t('notifications.previous') }}</button><span>{{ courseIds.length }}</span><button type="button" :disabled="coursePage >= courseLastPage" class="min-h-11 px-3" @click="loadCourses(coursePage + 1)">{{ t('notifications.next') }}</button></div></fieldset><label class="block">{{ t('notifications.schedule') }}<input v-model="form.publish_at" type="datetime-local" class="min-h-11 rounded-xl border border-slate-300 px-3" :disabled="!auth.can('announcements.publish')"></label><label class="block">{{ t('notifications.expiration') }}<input v-model="form.expires_at" type="datetime-local" class="min-h-11 rounded-xl border border-slate-300 px-3"></label><p v-if="preview !== null" role="status">{{ t('notifications.previewCount', { count: preview }) }}</p><div class="flex flex-wrap gap-3"><button type="button" class="min-h-11 rounded-xl border px-4" :disabled="busy" @click="act(previewAudience)">{{ t('notifications.preview') }}</button><button class="min-h-11 rounded-xl bg-primary px-4 text-brand-dark" :disabled="busy">{{ t('notifications.save') }}</button><button type="button" class="min-h-11 px-4" @click="form = null">{{ t('notifications.close') }}</button></div></form><article v-for="item in items" :key="item.id" class="space-y-3 rounded-2xl border border-slate-200 bg-white p-4"><h2 class="font-bold">{{ item.title[locale] }}</h2><p class="text-sm text-slate-500">{{ t(`notifications.statuses.${item.status}`) }} · {{ item.read_count }}/{{ item.recipients }}</p><div class="flex flex-wrap gap-3"><button v-if="['draft', 'scheduled'].includes(item.status)" type="button" class="min-h-11 px-3 text-brand" @click="start(item)">{{ t('notifications.edit') }}</button><button v-if="auth.can('announcements.publish') && ['draft', 'scheduled'].includes(item.status)" type="button" class="min-h-11 px-3 text-brand" :disabled="busy" @click="publish(item.id)">{{ t('notifications.publish') }}</button><button v-if="auth.can('announcements.publish') && item.status !== 'archived'" type="button" class="min-h-11 px-3 text-red-700" :disabled="busy" @click="archive(item.id)">{{ t('notifications.archive') }}</button></div></article><div v-if="meta.last_page > 1" class="flex justify-between"><button class="min-h-11 px-3" :disabled="meta.current_page <= 1" @click="load(meta.current_page - 1)">{{ t('notifications.previous') }}</button><button class="min-h-11 px-3" :disabled="meta.current_page >= meta.last_page" @click="load(meta.current_page + 1)">{{ t('notifications.next') }}</button></div></section></template>
